VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_111'), 1, 'Ask what Lighthouse does during a run: does anyone tap a button? Which metric needs a real interaction to exist?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_111'), 2, 'Sort the visits and count to the 75th one. The assessment never looks at the average.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_111'), 3, 'INP attribution splits one interaction into input delay, processing duration and presentation delay. Which part did the network play in?');
