-- challenge chal_coding_fwp_112 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_112', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-1-1' AND is_deleted = false LIMIT 1), 'rum-vitals-summary', 'Summarize the Core Web Vitals beacons', 'Rice Rocket''s RUM endpoint collects the beacons that the web-vitals library sends from real visits (`onLCP`, `onINP`, `onCLS`, attribution build). Complete `summarize(beacons)`, which turns them into one line per page and metric the way the Core Web Vitals assessment reads them. The editor holds the module with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Rules: web-vitals reports INP and CLS again when they grow, so for each `id` only the last beacon counts; `p75` is the 75th percentile by nearest rank (sort ascending, take item `ceil(0.75 * n)`); the rating uses the published thresholds (LCP 2500 / 4000 ms, INP 200 / 500 ms, CLS 0.1 / 0.25: at or below the first is good, at or below the second needs improvement, above is poor); `culprit` is the attribution `target` that appears most often among the samples at or above p75 (ties: alphabetical). Run feeds it batches of beacons.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
