INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_112'), 1, 'Work one page and metric at a time: which beacons are really the same visit, what is the 75th value after sorting, which band does it fall in, and who owns the slow samples?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_112'), 2, 'Look at a Map keyed by `id` (a later `set` replaces an earlier one), `Math.ceil(values.length * 0.75) - 1` as an index into the sorted values, and comparisons with `<=` against each threshold pair.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_112'), 3, 'A p90 of API latencies by route with a slowest-endpoint owner looks like: group by route, `const sorted = ms.sort((a, b) => a - b); const p90 = sorted[Math.ceil(sorted.length * 0.9) - 1];`, then count `owner` over the calls with `ms >= p90` and take the most frequent.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_112'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"latest-per-id","label":"Keep only the latest report of each metric instance","code":"const latest = new Map();\nfor (const beacon of beacons) latest.set(beacon.id, beacon);"},{"id":"p75","label":"The 75th percentile value (nearest rank)","code":"const values = samples.map((s) => s.value).sort((a, b) => a - b);\nconst p75 = values[Math.ceil(values.length * 0.75) - 1];"},{"id":"rate","label":"Good, needs improvement or poor by the metric''s thresholds","code":"const [good, poor] = THRESHOLDS[name];\nconst rating = p75 <= good ? \"good\" : p75 <= poor ? \"needs-improvement\" : \"poor\";"},{"id":"culprit","label":"The target behind most samples at or above p75","code":"const counts = new Map();\nfor (const s of samples) if (s.value >= p75) counts.set(s.target, (counts.get(s.target) || 0) + 1);\nconst culprit = [...counts].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))[0][0];"},{"id":"latest-keep-first","label":"Keep only the latest report of each metric instance","code":"const latest = new Map();\nfor (const beacon of beacons) if (!latest.has(beacon.id)) latest.set(beacon.id, beacon);","distractor":true},{"id":"p75-average","label":"The 75th percentile value (nearest rank)","code":"const values = samples.map((s) => s.value).sort((a, b) => a - b);\nconst p75 = Math.round((values.reduce((sum, v) => sum + v, 0) / values.length) * 1000) / 1000;","distractor":true},{"id":"rate-fid-thresholds","label":"Good, needs improvement or poor by the metric''s thresholds","code":"const [good, poor] = name === \"INP\" ? [100, 300] : THRESHOLDS[name];\nconst rating = p75 <= good ? \"good\" : p75 <= poor ? \"needs-improvement\" : \"poor\";","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
