       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_112'), 'Home page: LCP needs improvement, CLS at exactly 0.1 is good, INP 160 ms is good', '{"beacons":[{"page":"/","name":"LCP","id":"v13-LCP","value":1800,"target":"img.hero"},{"page":"/","name":"LCP","id":"v14-LCP","value":2100,"target":"img.hero"},{"page":"/","name":"LCP","id":"v15-LCP","value":2300,"target":"img.hero"},{"page":"/","name":"LCP","id":"v16-LCP","value":2600,"target":"img.hero"},{"page":"/","name":"LCP","id":"v17-LCP","value":2700,"target":"h1.promo"},{"page":"/","name":"LCP","id":"v18-LCP","value":2900,"target":"img.hero"},{"page":"/","name":"LCP","id":"v19-LCP","value":3300,"target":"img.hero"},{"page":"/","name":"LCP","id":"v20-LCP","value":5200,"target":"h1.promo"},{"page":"/","name":"CLS","id":"v21-CLS","value":0,"target":"body"},{"page":"/","name":"CLS","id":"v22-CLS","value":0.02,"target":"div.promo-banner"},{"page":"/","name":"CLS","id":"v23-CLS","value":0.05,"target":"img.dish-card"},{"page":"/","name":"CLS","id":"v24-CLS","value":0.08,"target":"div.promo-banner"},{"page":"/","name":"CLS","id":"v25-CLS","value":0.1,"target":"div.promo-banner"},{"page":"/","name":"CLS","id":"v26-CLS","value":0.12,"target":"div.promo-banner"},{"page":"/","name":"CLS","id":"v27-CLS","value":0.3,"target":"img.dish-card"},{"page":"/","name":"CLS","id":"v28-CLS","value":0.02,"target":"body"},{"page":"/","name":"INP","id":"v29-INP","value":60,"target":"input#search"},{"page":"/","name":"INP","id":"v30-INP","value":80,"target":"input#search"},{"page":"/","name":"INP","id":"v31-INP","value":100,"target":"a.nav"},{"page":"/","name":"INP","id":"v32-INP","value":120,"target":"a.nav"},{"page":"/","name":"INP","id":"v33-INP","value":140,"target":"input#search"},{"page":"/","name":"INP","id":"v34-INP","value":160,"target":"button.locate"},{"page":"/","name":"INP","id":"v35-INP","value":180,"target":"button.locate"},{"page":"/","name":"INP","id":"v36-INP","value":240,"target":"button.locate"}]