-- challenge chal_coding_fwp_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_122', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-1-2' AND is_deleted = false LIMIT 1), 'cart-recalc-yielding', 'Reprice the cart without blocking taps', 'Applying a promo code to a large group order reprices every line in one loop: about 600 ms on a budget phone, and every tap in the meantime waits (INP 640 ms on /cart). Complete `recalcCart(items, promo, env)` so it works in slices and yields to the main thread between them. The editor holds `cart/recalc.js` with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Rules: price every line with `env.price(item)` (it takes main-thread time) and add a discount of `round(line * percent / 100)` for lines in the promo''s category; once the current slice has used `env.budgetMs`, await `env.yield()` and start a new slice; do not yield while the work still fits in one slice; when `env.signal` is aborted (a newer promo code was applied), stop and return `null` without rendering; otherwise render the totals `{ subtotal, discount, total }` once and return them. Run measures the longest task, the delay of every tap and the number of yields on a simulated main thread.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_122');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_122'), 1, 'Picture the main thread as one queue: a tap can only run between two tasks. Where does one task end in your loop, and how long can it get?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_122'), 2, 'Look at `env.now()` before and after the work, `await env.yield()` (without `await` nothing waits for it), a slice start that moves forward after each yield, and `env.signal.aborted` after a yield.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_122'), 3, 'Sending 5,000 analytics events without freezing the page looks like: `let start = performance.now(); for (const e of events) { queue(e); if (performance.now() - start >= 40) { await scheduler.yield(); start = performance.now(); } if (signal.aborted) return; } flush();`');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_122'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"slice-start","label":"Remember when the current slice of work started","code":"let sliceStart = env.now();"},{"id":"price-item","label":"Price one line and add it to the totals","code":"const line = env.price(item);\nsubtotal += line;\nif (promo && promo.category === item.category) discount += Math.round((line * promo.percent) / 100);"},{"id":"yield-over-budget","label":"Give the main thread back once the slice used its budget","code":"if (env.now() - sliceStart >= env.budgetMs) {\n    await env.yield();\n    sliceStart = env.now();\n}"},{"id":"stop-if-stale","label":"Stop quietly when a newer recalculation replaced this one","code":"if (env.signal.aborted) return null;"},{"id":"render-once","label":"Show the new totals once, at the end","code":"const totals = { subtotal, discount, total: subtotal - discount };\nenv.render(totals);\nreturn totals;"},{"id":"slice-never-reset","label":"Give the main thread back once the slice used its budget","code":"if (env.now() - sliceStart >= env.budgetMs) {\n    await env.yield();\n}","distractor":true},{"id":"stale-still-renders","label":"Stop quietly when a newer recalculation replaced this one","code":"if (env.signal.aborted) break;","distractor":true},{"id":"yield-without-await","label":"Give the main thread back once the slice used its budget","code":"if (env.now() - sliceStart >= env.budgetMs) {\n    env.yield();\n    sliceStart = env.now();\n}","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
