INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131'), 1, 'Throttle sends during a burst, debounce after it. Which partial words would a throttled search send for "com tam suon"?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131'), 2, 'Look at the Duration column: does an earlier request have to finish earlier?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131'), 3, 'In the trace, what forces the browser to compute layout in the middle of the handler, and how often does the handler run per frame?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131'), 'The search box sends a request on every keystroke. A teammate proposes:

```js
searchInput.addEventListener("input", throttle((e) => search(e.target.value), 250));
```

Statement: "Throttling is the right fix for a search box: it sends the query at most every 250 ms while the user types, so only the final text reaches the API."', 'single_choice'::question_type, 'False. Throttle runs at most once per interval during a burst, so while someone types "com tam suon" it still sends "co", "com t", "com tam s"... Partial queries cost requests and flash irrelevant results. Debounce waits until the input has been quiet for the interval and then sends once, with the final text. Throttle fits continuous signals you want to sample while they happen (scroll position, resize, drag).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131'), 'The Network panel while typing "com tam":

```text
Name               Started   Duration
search?q=com       0 ms      820 ms
search?q=com%20t   310 ms    140 ms
search?q=com%20tam 620 ms    120 ms
```

Statement: "Responses come back in the order the requests were sent, so the last response always belongs to the last query."', 'single_choice'::question_type, 'False. Each request has its own latency: here "com" (a broad query, cache miss) finishes at 820 ms, after "com tam" finished at 740 ms, and if the code shows whatever arrives last, the list jumps back to the results for "com". Abort the previous request (AbortController) and, because not every client can cancel, ignore any answer that is not for the newest query.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131'), 'The sticky cart bar updates on scroll:

```js
window.addEventListener("scroll", () => {
  bar.style.transform = `translateY(${Math.min(0, lastY - window.scrollY)}px)`;
  lastY = window.scrollY;
  shadow.hidden = bar.getBoundingClientRect().top < 0;
});
```

```text
Performance: scroll handler 118 calls/s, each with "Recalculate Style" + "Layout" (forced reflow)
```

Statement: "Reading `getBoundingClientRect()` right after writing a style forces a synchronous layout on every scroll event; doing the work once per frame in a `requestAnimationFrame` callback, with a passive listener, removes it."', 'single_choice'::question_type, 'True. Writing `style.transform` invalidates layout, and reading a layout value right after makes the browser compute layout immediately, inside the handler: a forced reflow, more than once per frame because scroll events can outnumber frames. Coalescing into one `requestAnimationFrame` callback per frame (read first, then write) and `{ passive: true }` (the listener promises not to call `preventDefault`) keep scrolling smooth. CSS `position: sticky` can remove the script entirely.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_131') AND order_index = 3)
    RETURNING id
)
