-- challenge chal_coding_fwp_132 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_132', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-2-1' AND is_deleted = false LIMIT 1), 'dish-search-box', 'Fix the dish search box', 'The dish search on the menu page sent a request on every keystroke (12 requests for "com tam suon"), kept old requests running, and sometimes replaced the results for "pho bo" with the late results for "pho". The editor holds the corrected `search/searchBox.js` with its key blocks missing, each marked by a `// [ ]` line; the pieces that are wrong are last week''s bugs. Fill every line so that: `onInput(text)` searches only after typing pauses for `waitMs`, with the text trimmed; starting a search cancels the request still running (`AbortController`); and results are shown only if they belong to the newest search, because the old search SDK ignores the abort signal. Run types into a simulated box with fake timers and a search API whose answers arrive out of order.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
