INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_132'), 1, 'Follow one burst of typing: how many timers are pending after the third keystroke, how many requests are open after the second search starts, and which answer arrives last?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_132'), 2, 'Look at `env.clearTimeout(timer)` before setting a new timer, `controller.abort()` on the previous controller, and a request counter compared when the answer arrives.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_132'), 3, 'An autosave that waits for a pause and keeps only the latest save looks like: `clearTimeout(t); t = setTimeout(async () => { prev?.abort(); prev = new AbortController(); const v = ++version; const saved = await api.save(doc, { signal: prev.signal }); if (v === version) markSaved(saved); }, 800);`');
