       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_132'), 'The SDK ignores the abort: the late answer for "pho" never replaces "pho bo"', '{"waitMs":250,"typing":[{"at":0,"text":"p"},{"at":80,"text":"ph"},{"at":160,"text":"pho"},{"at":700,"text":"pho "},{"at":780,"text":"pho b"},{"at":860,"text":"pho bo"}],"latency":{"pho":900,"pho bo":100},"honorsAbort":false}', '{"requests":["pho","pho bo"],"shown":[["pho bo 1","pho bo 2"]],"maxInFlight":2}', 6, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_132'), 'Leading and trailing spaces are trimmed before the query is sent', '{"waitMs":250,"typing":[{"at":0,"text":" "},{"at":80,"text":"  "},{"at":160,"text":"  b"},{"at":240,"text":"  bu"},{"at":320,"text":"  bun"},{"at":400,"text":"  bun "},{"at":480,"text":"  bun c"},{"at":560,"text":"  bun ch"},{"at":640,"text":"  bun cha"},{"at":900,"text":"  bun cha "}],"latency":{},"honorsAbort":true}', '{"requests":["bun cha","bun cha"],"shown":[["bun cha 1","bun cha 2"],["bun cha 1","bun cha 2"]],"maxInFlight":1}', 6, false, true, 4),
