-- challenge chal_coding_fwp_142 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_142', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-2-2' AND is_deleted = false LIMIT 1), 'menu-virtual-window', 'Render only the rows in view', 'The food-court menu lists up to 3,000 rows: 40 px stall headers and 96 px dishes. Rendering all of them built 45,000 DOM nodes and made scrolling stutter on budget phones; keying rows by index also showed the wrong photos after the vegetarian filter. Complete `visibleWindow(rows, viewport, options)`, the calculation behind the virtualized list. The editor holds `menu/virtualWindow.js` with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Rules: compute each row''s top from the heights; the first visible row is the first whose bottom is below `scrollTop` (find it with a binary search, the list is long); rows that start at or below `scrollTop + height` are not visible; add `overscan` rows (default 3) on each side without leaving the list; return `start`, `end` (exclusive), `offsetTop` (top of row `start`), `totalHeight` and the `keys` of rows `start..end-1`, taken from each row''s `id`. Run calls it for several scroll positions, list shapes and a filtered list.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_142');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_142'), 1, 'Draw the list as stacked boxes with their top positions: which box contains the scroll position, which box starts at the bottom edge, and what happens near position 0 or at the end of the list?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_142'), 2, 'Look at an array of tops with one extra entry (the total height), a `while (lo < hi)` binary search on `tops[mid + 1] <= scrollTop`, `Math.max` / `Math.min` around the overscan, and `row.id` for keys.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_142'), 3, 'Finding which log lines of variable height are on screen in a log viewer looks like: `const tops = [0]; lines.forEach((l, i) => tops.push(tops[i] + l.h));` then a binary search for the first line with `tops[i + 1] > scrollY`, a walk while `tops[j] < scrollY + viewH`, and keys from `line.seq`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_142'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"prefix-tops","label":"Top position of every row, and the total height","code":"const tops = new Array(rows.length + 1);\ntops[0] = 0;\nfor (let i = 0; i < rows.length; i++) tops[i + 1] = tops[i] + rows[i].height;"},{"id":"first-visible","label":"First row whose bottom is below the scroll position","code":"let lo = 0;\nlet hi = rows.length;\nwhile (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (tops[mid + 1] <= viewport.scrollTop) lo = mid + 1;\n    else hi = mid;\n}\nconst first = lo;"},{"id":"past-last-visible","label":"First row that starts at or below the viewport''s bottom edge","code":"const bottom = viewport.scrollTop + viewport.height;\nlet last = first;\nwhile (last < rows.length && tops[last] < bottom) last++;"},{"id":"add-overscan","label":"Extra rows above and below, kept inside the list","code":"const start = Math.max(0, first - overscan);\nconst end = Math.min(rows.length, last + overscan);"},{"id":"row-keys","label":"Keys that follow the row, not its position","code":"const keys = rows.slice(start, end).map((row) => row.id);"},{"id":"overscan-unclamped","label":"Extra rows above and below, kept inside the list","code":"const start = first - overscan;\nconst end = last + overscan;","distractor":true},{"id":"past-last-inclusive","label":"First row that starts at or below the viewport''s bottom edge","code":"const bottom = viewport.scrollTop + viewport.height;\nlet last = first;\nwhile (last < rows.length && tops[last] <= bottom) last++;","distractor":true},{"id":"row-keys-index","label":"Keys that follow the row, not its position","code":"const keys = rows.slice(start, end).map((row, i) => String(start + i));","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
