-- challenge chal_quiz_fwp_151 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_fwp_151', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-2-3' AND is_deleted = false LIMIT 1), 'memoization-quiz', 'Read the menu page profile', 'Three statements about what the React Profiler showed on Rice Rocket''s menu page while a customer typed in the search box. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151'), 1, '`memo` compares each prop with `Object.is`. Is an arrow function written inside the parent''s render the same object on the next render?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151'), 2, 'Look at the cost column: which work takes milliseconds, and which takes microseconds? A memoized value also costs a dependency check on every render.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151'), 3, 'Read what the React Compiler documentation says about code that already calls `useMemo` and `useCallback`: does the compiler refuse it, or work alongside it?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151'), 'Every keystroke in the search box re-renders all 300 menu cards, although `MenuItem` is wrapped in `memo`:

```jsx
const MenuItem = memo(function MenuItem({ item, onAdd }) { /* ... */ });

// in MenuPage
{visible.map((item) => (
  <MenuItem key={item.id} item={item} onAdd={() => addToCart(item.id)} />
))}
```

```text
React Profiler, commit 14 (typed "p")
MenuItem (memo)  x300   Why did this render? Props changed: (onAdd)
```

Statement: "Since `MenuItem` is wrapped in `memo`, the 300 renders must come from a context or a store it reads, not from its props."', 'single_choice'::question_type, 'False. The Profiler names the prop: `onAdd`. `() => addToCart(item.id)` creates a new function on every render of MenuPage, so `Object.is(prev.onAdd, next.onAdd)` is false for every card and `memo` renders all of them. Pass one stable handler (`useCallback((id) => addToCart(id), [addToCart])`) and let the card call it with its own id. The misconception is that `memo` alone prevents renders; it only skips them when every prop is the same object or value.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151'), 'The profile of one keystroke on the 300-dish menu:

```text
MenuPage render              9.4 ms
  filterMenu(items, query)   8.1 ms
  formatPrice x 300          0.2 ms   (already wrapped in useMemo per card)
```

Statement: "The memoization that pays here is `useMemo` around `filterMenu` keyed on `[items, query]`; wrapping a cheap computation like `formatPrice` in `useMemo` adds a dependency check per render and saves almost nothing."', 'single_choice'::question_type, 'True. `useMemo` is worth its cost when the computation is expensive (8 ms of filtering) or when the result''s identity matters to a memoized child. For cheap work, the hook''s own bookkeeping (storing the value, comparing dependencies every render) costs about as much as it saves, and it makes the code harder to read. Measure first, then memoize the expensive step.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151') AND order_index = 2)
    RETURNING id
)
