SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151'), 'The team turns on the React Compiler in the Next.js app and runs the build:

```js
// next.config.js
const nextConfig = { reactCompiler: true };
```

Statement: "With the React Compiler enabled, every hand-written `useMemo`, `useCallback` and `memo` must be deleted first, or the build fails."', 'single_choice'::question_type, 'False. The compiler memoizes components and hooks automatically and works alongside existing manual memoization; it does not reject code that already uses `useMemo`, `useCallback` or `memo`. React''s guidance is to keep existing memoization (removing it can change behavior, for example effect dependencies) and to rely on the compiler for new code. The misconception is that automatic and manual memoization conflict. Hedge: check the exact option name for your Next.js version.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_151') AND order_index = 3)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_fwp_152 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_152', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-2-3' AND is_deleted = false LIMIT 1), 'menu-page-memoization', 'Fix the menu page memoization', 'Rice Rocket''s menu page re-renders every dish card on each keystroke, a teammate''s quick fix shows stale search results, and after a guest logs in the Add button still fills the guest''s cart. The editor holds `app/restaurants/[slug]/menu-page.jsx` as plain functions (the grader provides React''s `memo`, `useMemo` and `useCallback` with the same rules, and `render()` for writing a `<Component />`), with the four blocks of `MenuPage` missing, each marked by a `// [ ]` line; some pieces are last week''s buggy versions. Fill every line so that: the expensive `filterMenu` runs only when the dishes or the query change and the results always match the query; a card renders again only when its own props change (narrowing the search or adding one dish to the cart re-renders nothing else); and Add always calls the `addToCart` of the current customer. Run renders the page through a sequence of updates and counts card renders and filter runs.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
