INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_152'), 1, 'For each prop a card receives, ask: is it the same object on the next render when nothing about this dish changed? A new function or a new array each render defeats `memo`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_152'), 2, 'Look at the dependency arrays: every value the memoized function reads from the component''s scope belongs in them, and nothing else.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_152'), 3, 'A product list with a stable remove handler looks like: `const visible = useMemo(() => sortProducts(products, sort), [products, sort]); const onRemove = useCallback((id) => removeItem(id), [removeItem]); return visible.map((p) => <Row key={p.id} product={p} selected={selectedIds.has(p.id)} onRemove={onRemove} />);`');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_152'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"filter-memo","label":"Filter again only when the dishes or the query change","code":"const visible = useMemo(() => filterMenu(items, query), [items, query]);"},{"id":"cart-set","label":"Which dishes are in the cart, rebuilt when the cart changes","code":"const inCart = useMemo(() => new Set(cartIds), [cartIds]);"},{"id":"stable-add","label":"One add handler that follows the current addToCart","code":"const onAdd = useCallback((id) => addToCart(id), [addToCart]);"},{"id":"render-cards","label":"One card per dish with only the props it needs","code":"return visible.map((item) => render(MenuItem, { item, inCart: inCart.has(item.id), onAdd }));"},{"id":"filter-memo-items-only","label":"Filter again only when the dishes or the query change","code":"const visible = useMemo(() => filterMenu(items, query), [items]);","distractor":true},{"id":"stable-add-empty-deps","label":"One add handler that follows the current addToCart","code":"const onAdd = useCallback((id) => addToCart(id), []);","distractor":true},{"id":"stable-add-inline","label":"One add handler that follows the current addToCart","code":"const onAdd = (id) => addToCart(id);","distractor":true}]'::jsonb)
