-- challenge chal_coding_fwp_162 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_162', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-3-1' AND is_deleted = false LIMIT 1), 'restaurant-page-loader', 'Remove the restaurant page waterfall', 'The restaurant page of Rice Rocket''s Next.js app awaited five requests one after another (restaurant, menu, cart, reviews, recommendations): about 940 ms before anything could render, and the hero image only started downloading after all of them. The editor holds `app/restaurants/[slug]/load.js` with its blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: every request that needs only the slug starts at once; the recommendations start the moment the menu''s category ids are known; the hero image is preloaded the moment the restaurant''s data arrives; the reviews start as soon as the restaurant id is known but the loader does not wait for them (it returns them as a promise for a `<Suspense>` boundary); and each endpoint is called once. Run executes the loader against a fake API on a virtual clock and reports when each request started and when the page was ready.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
