INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 1, 'Draw the dependency graph: which requests need nothing but the slug, which need data from another response, and which does the first paint not need at all?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 2, 'A promise starts its work when you call the function, not when you `await` it. Keep the promises in variables, chain dependent calls with `.then`, and `await Promise.all([...])` only what must be ready.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 3, 'A product page with a deferred Q&A section looks like: `const productP = api.product(id); const priceP = api.price(id); const similarP = productP.then((p) => api.similar(p.categoryId)); const qaP = productP.then((p) => api.questions(p.sku)); const [product, price, similar] = await Promise.all([productP, priceP, similarP]); return { product, price, similar, questions: qaP };`');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"start-independent","label":"Start every request that needs only the slug","code":"const restaurantP = api.restaurant(slug);\nconst menuP = api.menu(slug);\nconst cartP = api.cart();"},{"id":"preload-hero","label":"Fetch the hero image as soon as its URL is known","code":"restaurantP.then((restaurant) => api.preload(restaurant.heroImage));"},{"id":"recommendations-after-menu","label":"Recommendations once the menu''s categories are known","code":"const recommendationsP = menuP.then((menu) => api.recommendations(menu.categories.map((c) => c.id)));"},{"id":"reviews-deferred","label":"Reviews once the restaurant id is known, not awaited","code":"const reviewsP = restaurantP.then((restaurant) => api.reviews(restaurant.id));"},{"id":"await-critical","label":"Wait only for what the first paint needs","code":"const [restaurant, menu, cart, recommendations] = await Promise.all([restaurantP, menuP, cartP, recommendationsP]);\nreturn { restaurant, menu, cart, recommendations, reviews: reviewsP };"},{"id":"await-critical-with-reviews","label":"Wait only for what the first paint needs","code":"const [restaurant, menu, cart, recommendations, reviews] = await Promise.all([restaurantP, menuP, cartP, recommendationsP, reviewsP]);\nreturn { restaurant, menu, cart, recommendations, reviews };","distractor":true},{"id":"preload-hero-after-menu","label":"Fetch the hero image as soon as its URL is known","code":"Promise.all([restaurantP, menuP]).then(([restaurant]) => api.preload(restaurant.heroImage));","distractor":true},{"id":"start-independent-chained","label":"Start every request that needs only the slug","code":"const restaurantP = api.restaurant(slug);\nconst menuP = restaurantP.then(() => api.menu(slug));\nconst cartP = menuP.then(() => api.cart());","distractor":true}]'::jsonb)
