VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 'The page is ready at 330 ms with the restaurant, menu, cart and recommendations', '{"slug":"com-tam-ba-ghien","latency":{"restaurant":120,"menu":180,"cart":90,"reviews":400,"recommendations":150}}', '{"readyAt":330,"starts":{"restaurant":0,"menu":0,"cart":0,"preload":120,"reviews":120,"recommendations":180},"calls":{"restaurant":1,"menu":1,"cart":1,"preload":1,"reviews":1,"recommendations":1},"page":{"restaurant":"Com Tam Ba Ghien","dishes":24,"cartItems":2,"recommendations":["d05","d09"]},"reviews":{"deferred":true,"readyAt":520,"count":3}}', 10, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 'A slow menu delays only the menu and recommendations; reviews still stream at 520 ms', '{"slug":"com-tam-ba-ghien","latency":{"restaurant":120,"menu":600,"cart":90,"reviews":400,"recommendations":150}}', '{"readyAt":750,"starts":{"restaurant":0,"menu":0,"cart":0,"preload":120,"reviews":120,"recommendations":600},"calls":{"restaurant":1,"menu":1,"cart":1,"preload":1,"reviews":1,"recommendations":1},"page":{"restaurant":"Com Tam Ba Ghien","dishes":24,"cartItems":2,"recommendations":["d05","d09"]},"reviews":{"deferred":true,"readyAt":520,"count":3}}', 10, false, true, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_162'), 'Slow reviews (2 s) never hold back the first paint', '{"slug":"com-tam-ba-ghien","latency":{"restaurant":120,"menu":180,"cart":90,"reviews":2000,"recommendations":150}}', '{"readyAt":330,"starts":{"restaurant":0,"menu":0,"cart":0,"preload":120,"reviews":120,"recommendations":180},"calls":{"restaurant":1,"menu":1,"cart":1,"preload":1,"reviews":1,"recommendations":1},"page":{"restaurant":"Com Tam Ba Ghien","dishes":24,"cartItems":2,"recommendations":["d05","d09"]},"reviews":{"deferred":true,"readyAt":2120,"count":3}}', 10, false, true, 3);
