DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171'), 1, 'Work out the response''s age at the CDN, then compare it with the freshness lifetime (s-maxage) and with lifetime + stale-while-revalidate.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171'), 2, 'Read RFC 9111''s definitions of `no-cache` and `no-store`: which one forbids storing, and which one forbids using a stored copy without checking first?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171'), 3, 'A shared cache keys responses by URL (plus Vary). What does a cached `/api/cart` response contain, and who asks for that URL next?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171'), 'The menu API answers through the CDN with:

```text
Cache-Control: public, s-maxage=60, stale-while-revalidate=300
```

The CDN stored the menu 90 seconds ago. A customer opens the restaurant.

Statement: "The CDN answers at once with the stored menu and fetches a fresh copy from the origin in the background, because 90 s is past the 60 s lifetime but inside the 300 s stale-while-revalidate window."', 'single_choice'::question_type, 'True. At 90 s the response is stale (age > s-maxage 60) but within lifetime + stale-while-revalidate (60 + 300 s), so RFC 5861 lets the cache serve the stored copy immediately and revalidate asynchronously. The next customer gets the refreshed menu. Past 360 s the CDN must wait for the origin. The misconception is that a stale response always costs the user a round trip to the origin.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171'), 'The HTML of the restaurant pages is sent with:

```text
Cache-Control: no-cache
ETag: "r42-5f1c"
```

Statement: "`no-cache` means neither the browser nor the CDN stores the page, so every visit downloads the full HTML again."', 'single_choice'::question_type, 'False. `no-cache` allows storing but requires validation before every reuse: the cache sends `If-None-Match: "r42-5f1c"` and gets a small `304 Not Modified` while the page is unchanged, or the new page right after a deploy. The directive that forbids storing is `no-store`. The misconception comes from the name; `no-cache` is cheap revalidation, not no caching.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
