        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171'), 'Support received screenshots of a customer seeing someone else''s cart. The cart API was answering with:

```text
GET /api/cart   (cookie: session=...)
Cache-Control: public, max-age=30
```

```text
CDN log
12:01:03  /api/cart  MISS  -> origin (session of An)
12:01:11  /api/cart  HIT   age=8   (session of Binh)
```

Statement: "`private` (or `no-store`) keeps the CDN from storing the cart; the browser may still keep a `private` response for its own user."', 'single_choice'::question_type, 'True. The CDN keys the entry by URL, so Binh received An''s cart from the shared cache. `private` tells shared caches not to store the response while the user''s own browser still may; `no-store` forbids storing anywhere. Personalized responses (carts, profiles, anything decided by a cookie or token) must never be `public`. The misconception is that a session cookie on the request makes the CDN bypass its cache.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_fwp_171') AND order_index = 3)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_fwp_172 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_172', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-3-2' AND is_deleted = false LIMIT 1), 'caching-headers', 'Set the caching headers for each route', 'Rice Rocket''s Next.js app answered everything with the framework defaults: the hashed bundles were revalidated on every visit, menu edits took minutes to appear, and once a misconfigured rule let the CDN serve one customer''s cart to another. The editor holds `middleware.js` with the header rules missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: hashed files under `/_next/static/` are cached for a year and never revalidated; a restaurant''s menu (`/api/restaurants/<id>/menu`) is shared by the CDN, at most 60 s old when served fresh, and refreshed in the background for up to 300 s after that, while browsers always check with the CDN; the cart (`/api/cart`) is never stored anywhere; restaurant pages (`/restaurants/...`) are stored but checked on every visit; anything else is not stored. The browser reads `Cache-Control`; the CDN reads `CDN-Cache-Control` when present. Run plays timelines of requests from several customers through their browsers, the CDN and the origin.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
