INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 1, 'For each route ask three questions: may a shared cache store it, how long is it fresh, and what may happen once it is stale?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 2, 'Look at `immutable`, `max-age`, `no-cache`, `no-store`, `private` and `stale-while-revalidate`, and at how `CDN-Cache-Control` lets the CDN and the browser follow different rules for the same response.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 3, 'A product API on another site: `if (path.startsWith("/api/products/")) return { "Cache-Control": "no-cache", "CDN-Cache-Control": "max-age=120, stale-while-revalidate=600" };` and an account endpoint: `if (path === "/api/me") return { "Cache-Control": "private, no-store" };`');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"hashed-assets","label":"Build files whose name changes with their content","code":"if (path.startsWith(\"/_next/static/\")) return { \"Cache-Control\": \"public, max-age=31536000, immutable\" };"},{"id":"menu-api","label":"Menus: shared, a minute fresh, refreshed in the background","code":"if (/^\\/api\\/restaurants\\/[^/]+\\/menu$/.test(path)) {\n    return { \"Cache-Control\": \"no-cache\", \"CDN-Cache-Control\": \"max-age=60, stale-while-revalidate=300\" };\n}"},{"id":"cart-api","label":"The customer''s own cart","code":"if (path === \"/api/cart\") return { \"Cache-Control\": \"private, no-store\" };"},{"id":"html-pages","label":"Pages: checked on every visit, cheap when unchanged","code":"if (path.startsWith(\"/restaurants/\")) return { \"Cache-Control\": \"no-cache\" };"},{"id":"cart-api-public","label":"The customer''s own cart","code":"if (path === \"/api/cart\") return { \"Cache-Control\": \"public, max-age=30\" };","distractor":true},{"id":"hashed-assets-no-cache","label":"Build files whose name changes with their content","code":"if (path.startsWith(\"/_next/static/\")) return { \"Cache-Control\": \"public, no-cache\" };","distractor":true},{"id":"menu-api-max-age","label":"Menus: shared, a minute fresh, refreshed in the background","code":"if (/^\\/api\\/restaurants\\/[^/]+\\/menu$/.test(path)) return { \"Cache-Control\": \"public, max-age=300\" };","distractor":true}]'::jsonb)
