       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 'A menu edit reaches customers about a minute later; the CDN refreshes in the background', '{"requests":[{"t":0,"user":"an","path":"/api/restaurants/42/menu"},{"t":30,"user":"an","path":"/api/restaurants/42/menu"},{"t":70,"user":"binh","path":"/api/restaurants/42/menu"},{"t":71,"user":"an","path":"/api/restaurants/42/menu"}],"changes":[{"t":5,"path":"/api/restaurants/42/menu","version":"v2"}]}', '{"responses":[{"t":0,"user":"an","path":"/api/restaurants/42/menu","from":"origin","status":200,"version":"v1"},{"t":30,"user":"an","path":"/api/restaurants/42/menu","from":"cdn","status":304,"version":"v1"},{"t":70,"user":"binh","path":"/api/restaurants/42/menu","from":"cdn-stale","status":200,"version":"v1"},{"t":71,"user":"an","path":"/api/restaurants/42/menu","from":"cdn","status":200,"version":"v2"}],"originHits":2,"leaks":0}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 'Each customer only ever sees their own cart', '{"requests":[{"t":0,"user":"an","path":"/api/cart"},{"t":10,"user":"binh","path":"/api/cart"},{"t":20,"user":"an","path":"/api/cart"}]}', '{"responses":[{"t":0,"user":"an","path":"/api/cart","from":"origin","status":200,"version":"cart-an"},{"t":10,"user":"binh","path":"/api/cart","from":"origin","status":200,"version":"cart-binh"},{"t":20,"user":"an","path":"/api/cart","from":"origin","status":200,"version":"cart-an"}],"originHits":3,"leaks":0}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 'Pages are checked on every visit: 304 while unchanged, the new deploy at once', '{"requests":[{"t":0,"user":"an","path":"/restaurants/com-tam-ba-ghien"},{"t":30,"user":"an","path":"/restaurants/com-tam-ba-ghien"},{"t":50,"user":"an","path":"/restaurants/com-tam-ba-ghien"}],"changes":[{"t":40,"path":"/restaurants/com-tam-ba-ghien","version":"v2"}]}', '{"responses":[{"t":0,"user":"an","path":"/restaurants/com-tam-ba-ghien","from":"origin","status":200,"version":"v1"},{"t":30,"user":"an","path":"/restaurants/com-tam-ba-ghien","from":"origin","status":304,"version":"v1"},{"t":50,"user":"an","path":"/restaurants/com-tam-ba-ghien","from":"origin","status":200,"version":"v2"}],"originHits":3,"leaks":0}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_fwp_172'), 'Lunch rush: 4 customers in 50 s cost the origin one menu request', '{"requests":[{"t":0,"user":"an","path":"/api/restaurants/42/menu"},{"t":15,"user":"binh","path":"/api/restaurants/42/menu"},{"t":30,"user":"chi","path":"/api/restaurants/42/menu"},{"t":50,"user":"dung","path":"/api/restaurants/42/menu"}]}', '{"responses":[{"t":0,"user":"an","path":"/api/restaurants/42/menu","from":"origin","status":200,"version":"v1"},{"t":15,"user":"binh","path":"/api/restaurants/42/menu","from":"cdn","status":200,"version":"v1"},{"t":30,"user":"chi","path":"/api/restaurants/42/menu","from":"cdn","status":200,"version":"v1"},{"t":50,"user":"dung","path":"/api/restaurants/42/menu","from":"cdn","status":200,"version":"v1"}],"originHits":1,"leaks":0}', 5, false, true, 5);
