-- challenge chal_coding_fwp_182 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_fwp_182', (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'frontend-web-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-fwp-3-3' AND is_deleted = false LIMIT 1), 'performance-budgets', 'Fail the build on a performance budget', 'Rice Rocket''s Lighthouse CI job collected three runs per page on every pull request, but nothing failed: a 600 KB analytics bundle and a hero image without dimensions both reached production. The editor holds `scripts/check-budgets.js` with its blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: each metric is judged on the median of the runs, so one noisy run neither fails nor passes a page on its own; a budget applies to the pages its pattern names (`*` stands for exactly one path segment); a budget at level `error` fails the build and one at level `warn` only warns; a metric listed under `regression` fails the build when it grew more than that fraction since main, even under its budget, and a page that is new on this branch has no baseline to compare with; errors come before warnings, each group sorted. Run checks reports built from real-looking runs.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
